impl Solution{pub fn letter_combinations(d:String)->Vec<String>{if d.is_empty(){return vec![]}let m=["","","abc","def","ghi","jkl","mno","pqrs","tuv","wxyz"];fn bt(d:&[u8],i:usize,m:&[&str;10],cur:&mut String,o:&mut Vec<String>){if i==d.len(){o.push(cur.clone());return}for c in m[(d[i]-b'0')as usize].chars(){cur.push(c);bt(d,i+1,m,cur,o);cur.pop();}}let mut o=vec![];bt(d.as_bytes(),0,&m,&mut String::new(),&mut o);o}}
